scripts.script:
if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === "unstable");
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, data);
        ui.notifications.info(`${args.target.name} 下盘不稳！`);
    }
}

if (!Macros.checkStance(actor, args)) return;

// 获取升级后的范围
const stanceId = actor.system.martial.stance;
const moveData = thisItem.system.moves.find(m => m.id === stanceId);
const lvl = Math.max(1, moveData?.computedLevel || 1);
const range = 1 + (lvl - 1);

// 查找旧的并删除
const oldEff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "xiaoyinzhang");
if (oldEff) await game.xjzl.api.effects.removeEffect(actor, "xiaoyinzhang", 1);

// 添加新AE作为标记
const effData = thisItem.effects.getName("箫音障").toObject();
delete effData._id;
effData.origin = thisItem.uuid;
effData.name = `箫音障 (${range}米)`;
await game.xjzl.api.effects.addEffect(actor, effData);

ui.notifications.info(`已生成箫音障 (半径${range}米)，请手动处理回合初伤害。`);

if (args.isHit) {
    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "qigan",
        dc: 16,
        label: "抵抗音波",
        onFail: "root"
    });
}

if (args.isBroken) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div class="card-header" style="border-bottom:1px solid #ccc; font-weight:bold; color:green;">箫心剑气 - 击破触发</div>
            <div style="padding:5px; font-size:0.9em;">
                <p>架招已击破！</p>
                <p>你可以立即消耗 <b>次要动作</b> 施展 <b>【清音徐徐】</b>。</p>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit) {
    const eff = CONFIG.statusEffects.find(e => e.id === "deaf");
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

if (args.isHit) {
    const hasMark = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "luoying_mark");
    if (hasMark) {
        // 倒地 (Prone)
        await game.xjzl.api.effects.toggleStatus(args.target, "prone", true);
        // 禁足 (Root)
        const rootEff = CONFIG.statusEffects.find(e => e.id === "root");
        if (rootEff) {
            const data = foundry.utils.deepClone(rootEff);
            data.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.target, data);
        }
        ui.notifications.info(`${args.target.name} 触发落英：倒地并禁足！`);
    }
}

if (!Macros.checkStance(actor, args)) return;

// 获取AE模板
const effData = thisItem.effects.getName("落英").toObject();
delete effData._id;
effData.origin = thisItem.uuid;

// 施加给攻击者
if (args.attacker) {
    await game.xjzl.api.effects.addEffect(args.attacker, effData);
    ui.notifications.info(`${args.attacker.name} 被标记 [落英]`);
}

if (args.isHit) {
    const hasMark = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "luoying_mark");
    if (hasMark) {
        await game.xjzl.api.effects.toggleStatus(args.target, "prone", true);
        const rootEff = CONFIG.statusEffects.find(e => e.id === "root");
        if (rootEff) {
            const data = foundry.utils.deepClone(rootEff);
            data.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.target, data);
        }
        ui.notifications.info(`${args.target.name} 触发落英：倒地并禁足！`);
    }
}

if (args.isHit) {
    const hasMark = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "luoying_mark");
    if (hasMark) {
        await game.xjzl.api.effects.toggleStatus(args.target, "prone", true);
        const rootEff = CONFIG.statusEffects.find(e => e.id === "root");
        if (rootEff) {
            const data = foundry.utils.deepClone(rootEff);
            data.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.target, data);
        }
        ui.notifications.info(`${args.target.name} 触发落英：倒地并禁足！`);
    }
}

if (args.isHit) {
    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "dingli",
        dc: 17,
        label: "抵抗音律",
        onFail: "zibi"
    });
}

if (args.outcome.isHit && !args.target.system.martial.stanceActive) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const dc = 15 + (lvl - 1) * 2;

    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "点指神通" },
        content: `<p>命中无架招目标！</p><p>是否<b>放弃伤害</b>转为<b>点穴</b>？</p><p>(DC: ${dc})</p>`,
        yes: { label: "点穴 (放弃伤害)", icon: "fas fa-bullseye" },
        no: { label: "仅造成伤害", icon: "fas fa-fist-raised" }
    });

    if (confirm) {
        // 伤害归零
        args.config.amount = 0;

        // 施加点穴状态
        const eff = CONFIG.statusEffects.find(e => e.id === "dianxue");
        if (eff) {
            const data = foundry.utils.deepClone(eff);
            data.duration = { rounds: 1 };
            // 记录解穴DC到AE上 (虽然系统目前没用到，但留作参考)
            data.flags["xjzl-system"] = { ...data.flags["xjzl-system"], dc: dc };
            await game.xjzl.api.effects.addEffect(args.target, data);
            ui.notifications.info(`${args.target.name} 被点穴 (DC ${dc})，伤害已豁免。`);
        }
    }
}

if (!Macros.checkStance(actor, args)) return;

const effData = thisItem.effects.getName("雕花").toObject();
delete effData._id;
effData.origin = thisItem.uuid;

// 动态计算烹饪加成 (1 + Lv-1)
const stanceId = actor.system.martial.stance;
const moveData = thisItem.system.moves.find(m => m.id === stanceId);
const lvl = Math.max(1, moveData?.computedLevel || 1);
const bonus = 1 + (lvl - 1);

effData.changes[0].value = String(bonus);
await game.xjzl.api.effects.addEffect(actor, effData);

const pengren = actor.system.arts.pengren.total || 0;
if (pengren >= 5 && !args.target.system.martial.stanceActive) {
    args.flags.critThresholdMod += 2;
}

const pengren = actor.system.arts.pengren.total || 0;
if (pengren >= 5) {
    args.output.feint += 2;
    args.output.feintBonusDesc.push("烹饪精通: 虚招+2");
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === "bleed_stack");
    if (eff) {
        await game.xjzl.api.effects.addEffect(args.target, eff);
    }
}

const hasDiaohua = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "diaohua");
if (hasDiaohua) {
    args.output.damage += 10;
    args.output.bonusDesc.push("雕花加成 +10");
}

const diaohua = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "diaohua");
if (diaohua) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "百千花刀" },
        content: `<p>检测到 [雕花]，伤害已 +10。</p><p>是否消耗 [雕花] 以生效此加成？</p>`,
        yes: { label: "消耗", icon: "fas fa-check" },
        no: { label: "不消耗", icon: "fas fa-times" }
    });

    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "diaohua", 1);
        ui.notifications.info("消耗 [雕花]，伤害提升并留下印记。 ");
    } else {
        args.flags.damageResult.damage -= 10;
        args.flags.damageResult.breakdown += "\n- 未消耗雕花：移除加成 (-10)";
    }
}

if (args.isHit) {
    const buff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huangjinbili");
    if (buff) {
        await game.xjzl.api.effects.removeEffect(actor, "huangjinbili", 1);
        await actor.applyHealing({ healer: actor, amount: 10, type: 'hp', showScrolling: true});
        await actor.applyHealing({ healer: actor, amount: 10, type: 'mp', showScrolling: true});
        ui.notifications.info(`${actor.name} 消耗 [黄金比例] 回复状态！`);
    }
}

// 基础回复已由 heal 模式处理(HP)，需额外处理MP
const lvl = Math.max(1, move.computedLevel || 1);
const amount = 5 + (lvl - 1) * 5;
await actor.applyHealing({ healer: actor, amount: amount, type: 'mp', showScrolling: true});

// 添加黄金比例
const eff = thisItem.effects.getName("黄金比例").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

ui.notifications.info("请手动消耗一个主食或小吃。");

if (args.isHit) {
    const buff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huangjinbili");
    if (buff) {
        await game.xjzl.api.effects.removeEffect(actor, "huangjinbili", 1);
        ui.notifications.info(`${actor.name} 消耗 [黄金比例]，请手动移除一个负面状态。`);
    }
}

const eff = thisItem.effects.getName("山珍").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

if (!Macros.checkStance(actor, args)) return;
const eff = thisItem.effects.getName("海味").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

const hasShan = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "shanzhen");
const hasHai = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "haiwei");
if (hasShan && hasHai) {
    S.combat.block += 10;
}

if (args.isBroken) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const pengren = actor.system.arts.pengren.total || 0;
    // 基础流失由等级成长决定? 原文说 升级:流失气血+10，这里假设烹饪*5是基础公式，升级增加额外值。
    // 修正理解：原文"流失等于你[烹饪]等级*5 的气血"，升级部分说"流失气血+10"。
    // 组合公式： (烹饪 * 5) + ((Lv-1) * 10)
    const bleedAmount = (pengren * 5) + ((lvl - 1) * 10);

    await args.target.applyDamage({
        amount: bleedAmount,
        type: "liushi",
        attacker: actor,
        isHit: true,
        ignoreDefense: true
    });

    await actor.applyHealing({ healer: actor, amount: bleedAmount, type: 'hp', showScrolling: true});
    ui.notifications.info(`击破吸血：造成 ${bleedAmount} 流失，回复自身。`);
}

const eff = thisItem.effects.getName("不时不食").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

if (args.isBroken) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div class="card-header" style="border-bottom:1px solid #ccc; color:red;">剜肉剔骨 - 击破</div>
            <div style="padding:5px; font-size:0.9em;">
                <p>击破架招！请随机削去一块血肉。</p>
                <p>若该部位已残缺，施加 <b>[骨折]</b> 状态。</p>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    ui.notifications.info("命中无架招目标：请手动处理 [脱臼] 效果。");
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === "endless_bleed");
    if (eff) {
        await game.xjzl.api.effects.addEffect(args.target, eff);
        ui.notifications.info(`${args.target.name} 头皮被削，血流不止！`);
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const pengren = actor.system.arts.pengren.total || 0;
    let effects = [];
    if (pengren >= 3) effects.push("Lv3: 全身削肉");
    if (pengren >= 5) effects.push("Lv5: 斩瞎双眼");
    if (pengren >= 7) effects.push("Lv7: 斩断指头 (1d4/处)");
    if (pengren >= 10) effects.push("Lv10: 斩断四肢之一");

    if (effects.length > 0) {
        ChatMessage.create({
            content: `<div class="xjzl-chat-card">
                <div class="card-header" style="border-bottom:1px solid #ccc; color:#8b0000;">猛牛青龙斩 - 烹饪特效 (Lv${pengren})</div>
                <ul style="padding-left:20px; margin:5px 0;">
                    ${effects.map(e => `<li>${e}</li>`).join('')}
                </ul>
            </div>`,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 5) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 5 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 5});

const isZuidao = actor.system.resources.alcohol.value > (actor.system.resources.alcohol.max || 0) || actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "zuidao");
if (isZuidao) {
    const eff = thisItem.effects.getName("醉态").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
}

if (!Macros.checkStance(actor, args)) return;
const isZuidao = actor.system.resources.alcohol.value > (actor.system.resources.alcohol.max || 0) || actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "zuidao");
if (isZuidao) {
    const eff = thisItem.effects.getName("醉态").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
}

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 5) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 5 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 5});

if (!args.isHit) return;
if (!args.target.system.martial.stanceActive) {
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-arrows-alt-h"></i> 急步挑灯</b><br>命中无架招目标！请手动击退 ${args.target.name} 1 米，并可消耗次要动作饮用一壶美酒。</div></div>` });
}

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 5) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 5 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 5});

if (!args.isHit) return;
if (args.isBroken) {
    const eff = thisItem.effects.getName("醉态").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #8e44ad; background: rgba(142, 68, 173, 0.1);"><b><i class="fas fa-wind"></i> 倒拍击飞</b><br>获得 1 层[醉态]！请手动击飞 ${args.target.name} 3 米。</div></div>` });
}

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 5) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 5 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 5});

if (!args.isHit) return;
await game.xjzl.api.effects.addEffect(args.target, {id: "zuidao", duration: {rounds: 3}});
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #27ae60; background: rgba(39, 174, 96, 0.1);"><b><i class="fas fa-wine-bottle"></i> 敬酒灌醉</b><br>${args.target.name} 陷入 [醉倒] 3回合！</div></div>` });

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 5) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 5 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 5});

const zuitai = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "zuitai");
const stacks = zuitai ? (zuitai.getFlag("xjzl-system", "stacks") || 1) : 0;
const options = [];
if (stacks >= 1) options.push({value: 1, label: "消耗1层：命中+10"});
if (stacks >= 2) options.push({value: 2, label: "消耗2层：击飞并倒地"});
if (stacks >= 3) options.push({value: 3, label: "消耗3层：伤害+20"});

if (options.length > 0) {
    const content = `<form><div class="form-group"><label>选择醉态强化 (互斥)</label><select id="choice"><option value="0">不消耗</option>${options.map(o => `<option value="${o.value}">${o.label}</option>`).join("")}</select></div></form>`;
    const choice = await foundry.applications.api.DialogV2.prompt({ window: { title: "醉仙指路 - 醉态爆发" }, content: content, ok: { callback: (e, b) => b.form.elements.choice.value } });
    const cost = parseInt(choice) || 0;
    if (cost > 0) {
        actor._zuitaiChoice = cost;
        if (cost === 1) { 
            args.flags.bonusHit += 10; 
            args.flags.damageResult.breakdown += "\n+ 醉态(1层): 命中+10"; 
        }
        else if (cost === 3) { 
            args.flags.damageResult.damage += 20; 
            args.flags.damageResult.breakdown += "\n+ 醉态(3层): 伤害+20"; 
        }

        const jiuyi = actor.system.arts.jiuyi.total || 0;
        if (jiuyi < 10) await game.xjzl.api.effects.removeEffect(actor, "zuitai", cost);
        else ui.notifications.info("酒艺高超(>=10)，消耗的醉态瞬间返还！");
    }
}

if (!args.isHit) return;
const zuitaiChoice = actor._zuitaiChoice || 0;
delete actor._zuitaiChoice;
if (zuitaiChoice === 2) {
    await game.xjzl.api.effects.addEffect(args.target, "prone");
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1);"><b><i class="fas fa-meteor"></i> 醉态爆发</b><br>${args.target.name} 已被击倒！请手动将其击飞 3 米。</div></div>` });
}

if (args.item?.name !== "醉棍") return;
const isZuidao = actor.system.resources.alcohol.value > (actor.system.resources.alcohol.max || 0) || actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "zuidao");
if (!isZuidao) return;
args.flags.damageResult.damage += 5;
args.flags.damageResult.breakdown += "\n+ 醉倒加成 +5";

if (!args.isHit) return;
if (args.item?.name !== "醉棍") return;
if (args.move?.targetInfo === "自身") return;
const isZuidao = actor.system.resources.alcohol.value > (actor.system.resources.alcohol.max || 0) || actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "zuidao");
if (!isZuidao) return;
await game.xjzl.api.effects.addEffect(args.target, "prone");
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #f39c12; background: rgba(243, 156, 18, 0.1);"><b><i class="fas fa-beer"></i> 醉倒发力</b><br>${args.target.name} 被击倒！</div></div>` });

const alc = actor.system.resources.alcohol.value || 0;
if (alc < 10) {
    args.flags.abort = true;
    args.flags.abortReason = "醉意不足 10 点，无法施展！";
    return;
}
await actor.update({"system.resources.alcohol.value": alc - 10});

const xianniang = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "xianniang");
if (xianniang) {
    const confirm = await foundry.applications.api.DialogV2.confirm({window: {title: "仙酿爆发"}, content: "<p>是否消耗 1 层 [仙酿] 提升当前醉意值的伤害？（随后将清空醉意）</p>", yes: {label: "爆发"}, no: {label: "否"}});
    if (confirm) {
        const currentAlc = actor.system.resources.alcohol.value || 0;
        args.flags.damageResult.damage += currentAlc;
        args.flags.damageResult.breakdown += `\n+ 仙酿爆发：+${currentAlc}`;
